"""OpenAI-style chat messages, one trajectory per JSON object.

Accepts `.jsonl` (one object per line) or `.json` (an object or a list of objects).
Field names are configurable so that close variants need no code.
"""

from __future__ import annotations

import json
from collections.abc import Iterator
from pathlib import Path
from typing import Any

from traj_analyzer.schema import Step, Trajectory

_ROLES = {"user": "user", "assistant": "assistant", "tool": "tool", "system": "system",
          "function": "tool", "human": "user", "gpt": "assistant"}


class MessagesAdapter:
    def __init__(
        self,
        messages_key: str = "messages",
        role_key: str = "role",
        content_key: str = "content",
        id_key: str | None = "id",
        metadata_keys: list[str] | None = None,
    ) -> None:
        self.messages_key = messages_key
        self.role_key = role_key
        self.content_key = content_key
        self.id_key = id_key
        self.metadata_keys = metadata_keys

    def read(self, path: Path, dataset: str) -> Iterator[Trajectory]:
        for n, record in enumerate(_records(path)):
            ident = record.get(self.id_key) if self.id_key else None
            tid = str(ident) if ident is not None else f"{path.stem}-{n}"
            metadata = {k: v for k, v in record.items() if k != self.messages_key}
            if self.metadata_keys is not None:
                metadata = {k: metadata[k] for k in self.metadata_keys if k in metadata}
            yield Trajectory(id=tid, dataset=dataset, metadata=metadata,
                             steps=list(self._steps(record.get(self.messages_key) or [])))

    def _steps(self, messages: list[dict[str, Any]]) -> Iterator[Step]:
        index = 0
        for message in messages:
            role = _ROLES.get(str(message.get(self.role_key, "")).lower(), "system")
            content = message.get(self.content_key)
            if content:
                text = content if isinstance(content, str) else json.dumps(content, ensure_ascii=False)
                kind = "tool_result" if role == "tool" else "message"
                yield Step(index=index, role=role, kind=kind, content=text,  # type: ignore[arg-type]
                           name=message.get("name"))
                index += 1
            for call in message.get("tool_calls") or []:
                function = call.get("function", call)
                yield Step(index=index, role="assistant", kind="tool_call",
                           name=function.get("name"), content=str(function.get("arguments", "")))
                index += 1


def _records(path: Path) -> Iterator[dict[str, Any]]:
    text = path.read_text(encoding="utf-8")
    if path.suffix == ".jsonl":
        for line in text.splitlines():
            if line.strip():
                yield json.loads(line)
        return
    data = json.loads(text)
    yield from data if isinstance(data, list) else [data]
