                yield Step(index=0, role=kind, content=block.get("text", ""),  # type: ignore[arg-type]
                           timestamp=timestamp)
            elif btype == "thinking" and self.include_thinking and block.get("thinking"):
                yield Step(index=0, role="assistant", kind="thinking",
                           content=block["thinking"], timestamp=timestamp)
            elif btype == "tool_use":
                yield Step(index=0, role="assistant", kind="tool_call", name=block.get("name"),
                           content=json.dumps(block.get("input"), ensure_ascii=False),
                           timestamp=timestamp)
